package me.danialisntcool.factionfriction.faction;public class OperationAttack {public State state=State.ACTIVE;public int chunkX,chunkZ,blocksBroken,allocationPercent=100;public OperationAttack(int x,int z){chunkX=x;chunkZ=z;}public long chunkLong(){return net.minecraft.world.level.ChunkPos.asLong(chunkX,chunkZ);}public boolean isResolved(){return state==State.DEFENDED||state==State.CAPTURED;}public enum State{ACTIVE,DEFENDED,CAPTURED}}